import obsidianmd from "eslint-plugin-obsidianmd";
import eslintComments from "@eslint-community/eslint-plugin-eslint-comments";

// The community directory scanner runs eslint-plugin-obsidianmd's recommended set,
// and its errors block installability. Used as-is: transforming it breaks on
// upstream defects (a misspelled core rule, blocks applying rules they don't declare).

// docs.obsidian.md/community-directory/faq — paths the scanner never reads.
const SCANNER_IGNORES = [
  "node_modules", "dist", "build", "pkg", "test-vault", ".pnpm-store", ".obsidian",
  "esbuild.config.mjs", "version-bump.mjs", "automation",
  "*.test.*", "*.tests.*", "*.spec.*", "*.specs.*",
  "test", "tests", "__tests__", "testUtils", "e2e-tests", "mocks", "__mocks__",
  "*.cjs", "*.mjs", "*.cts", "*.mts",
  "vite", "scripts", "docs", "i18n", "i18next", "locale", "locales", "translations", "l10n",
].flatMap((p) => (p.includes("*") ? [p, `**/${p}`] : [`${p}/**`, `**/${p}/**`, p, `**/${p}`]));

// The subset the scanner keeps at error after downgrading the rest; these block
// installability. Ported from obsidianmd/obsidian-workflows src/lint.ts.
export const errorRules = {
  "no-eval": "error",
  "no-implied-eval": "error",
  "obsidianmd/regex-lookbehind": "error",
  "obsidianmd/no-forbidden-elements": "error",
  "obsidianmd/settings-tab/no-manual-html-headings": "error",
  "obsidianmd/settings-tab/no-problematic-settings-headings": "error",
  "obsidianmd/sample-names": "error",
  "obsidianmd/no-sample-code": "error",
  "obsidianmd/platform": "error",
  "obsidianmd/no-plugin-as-component": "error",
  "obsidianmd/detach-leaves": "error",
  "obsidianmd/no-static-styles-assignment": "error",
  "obsidianmd/no-view-references-in-plugin": "error",
  "obsidianmd/no-unsupported-api": "error",
  "eslint-comments/no-unlimited-disable": "error",
  "eslint-comments/require-description": "error",
  "eslint-comments/disable-enable-pair": ["error", { allowWholeFile: false }],
  "eslint-comments/no-restricted-disable": ["error", "obsidianmd/*", "no-console"],
};

export const errorPlugins = { obsidianmd, "eslint-comments": eslintComments };

/** @type {import("eslint").Linter.Config[]} */
export const config = [
  { ignores: SCANNER_IGNORES },
  ...obsidianmd.configs.recommended,
];
EOF
